oxy_webhelp_navlinks = {"rcv_networking_dc-d39536e10634":{"topics":[{"title":"Secure connectivity with Azure private endpoints","shortdesc":"<p class=\"shortdesc\">For data center workloads, an Azure private endpoint in your own Azure tenant sends         data from your Rubrik clusters to RCV over a private connection, such as ExpressRoute,         instead of the public internet.<\/p>","href":"saas\/rcv_secure_connectivity_azr_pe.html","attributes":{"data-id":"rcv_secure_connectivity_azr_pe"},"menu":{"hasChildren":false},"tocID":"rcv_secure_connectivity_azr_pe-d39536e10645","next":"rcv_secure_connectivity_azr_pe-d39536e10645"},{"title":"Enabling AWS private connectivity for an existing RCV location","shortdesc":"<p class=\"shortdesc\">Enable AWS VPC interface endpoints on an existing Rubrik Cloud Vault location for         data center workloads to route archival traffic over private network paths. You must disable         the location before making changes to its network settings.<\/p>","href":"saas\/rcv_configuring_aws_private_connectivity.html","attributes":{"data-id":"rcv_configuring_aws_private_connectivity"},"menu":{"hasChildren":false},"tocID":"rcv_configuring_aws_private_connectivity-d39536e10711","topics":[]},{"title":"Connecting a reader location","shortdesc":"<p class=\"shortdesc\">Connect a secondary Rubrik cluster to an existing RCV location as a reader to provide         read-only access to archived data.<\/p>","href":"saas\/rcv_connecting_reader_location.html","attributes":{"data-id":"rcv_connecting_reader_location"},"menu":{"hasChildren":false},"tocID":"rcv_connecting_reader_location-d39536e10722","topics":[]},{"title":"Configuring network settings for AWS RCV reader locations","shortdesc":"<p class=\"shortdesc\">When connecting a reader cluster to an AWS RCV location that has private connectivity         or an IP allow list configured, configure matching network settings during the Connect As         Reader wizard.<\/p>","href":"saas\/rcv_aws_reader_network_settings.html","attributes":{"data-id":"rcv_aws_reader_network_settings"},"menu":{"hasChildren":false},"tocID":"rcv_aws_reader_network_settings-d39536e10733","topics":[]}]}};